27	
28	/**
29	 * Simple JavaBean domain object representing an owner.
30	 *
31	 * @author Ken Krebs
32	 * @author Juergen Hoeller
33	 * @author Sam Brannen
34	 * @author Michael Isvy
35	 */
36	@Entity
37	@Table(name = "owners")
38	public class Owner extends Person {
39	    @Column(name = "address")
40	    @NotEmpty
41	    private String address;
42	
43	    @Column(name = "city")
44	    @NotEmpty
45	    private String city;
46	
47	    @Column(name = "telephone")
48	    @NotEmpty
49	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form")
50	    private String telephone;
51	
52	    @Column(name = "email")
53	    @Email
54	    private String email;
55	
56	    @Column(name = "registration_date")
57	    private LocalDate registrationDate;
58	
59	    @Column(name = "customer_code")
60	    private String customerCode;
61	
62	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
63	    private Set<Pet> pets;
64	
65	    public String getAddress() {
66	        return this.address;
67	    }
68	
69	    public void setAddress(String address) {
70	        this.address = address;
71	    }
72	
73	    public String getCity() {
74	        return this.city;
75	    }
76	
77	    public void setCity(String city) {
78	        this.city = city;
79	    }
80	
81	    public String getTelephone() {
82	        return this.telephone;
83	    }
84	
85	    public void setTelephone(String telephone) {
86	        this.telephone = telephone;
87	    }
88	
89	    public String getEmail() {
90	        return this.email;
91	    }
92	
93	    public void setEmail(String email) {
94	        this.email = email;
95	    }
96	
97	    public LocalDate getRegistrationDate() {
98	        return this.registrationDate;
99	    }
100	
101	    public void setRegistrationDate(LocalDate registrationDate) {
102	        this.registrationDate = registrationDate;
103	    }
104	
105	    public String getCustomerCode() {
106	        return this.customerCode;
107	    }
108	
109	    public void setCustomerCode(String customerCode) {
110	        this.customerCode = customerCode;
111	    }
112	
113	    /**
114	     * When no registration date is supplied, default it to the server's current date.
115	     * Running on {@link PrePersist} keeps this invariant true for every create path
116	     * (any controller, bulk import or test fixture) rather than a single entry point.
117	     */
118	    @PrePersist
119	    protected void onCreate() {
120	        if (this.registrationDate == null) {
121	            this.registrationDate = LocalDate.now();
122	        }
123	    }
124	
125	    protected Set<Pet> getPetsInternal() {
126	        if (this.pets == null) {
127	            this.pets = new HashSet<>();
128	        }
129	        return this.pets;
130	    }
131	
132	    protected void setPetsInternal(Set<Pet> pets) {
133	        this.pets = pets;
134	    }
135	
136	    public List<Pet> getPets() {
137	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
138	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
139	        return Collections.unmodifiableList(sortedPets);
140	    }
141	
142	    public void setPets(List<Pet> pets) {
143	        this.pets = new HashSet<>(pets);
144	    }
145	
146	    public void addPet(Pet pet) {
147	        getPetsInternal().add(pet);
148	        pet.setOwner(this);
149	    }
150	
151	    /**
152	     * Return the Pet with the given name, or null if none found for this Owner.
153	     *
154	     * @param name to test
155	     * @return true if pet name is already in use
156	     */
157	    public Pet getPet(String name) {
158	        return getPet(name, false);
159	    }
160	
161	    /**
162	     * Return the Pet with the given name, or null if none found for this Owner.
163	     *
164	     * @param name to test
165	     * @return true if pet name is already in use
166	     */
167	    public Pet getPet(String name, boolean ignoreNew) {
168	        name = name.toLowerCase();
169	        for (Pet pet : getPetsInternal()) {
170	            if (!ignoreNew || !pet.isNew()) {
171	                String compName = pet.getName();
172	                compName = compName.toLowerCase();
173	                if (compName.equals(name)) {
174	                    return pet;
175	                }
176	            }
177	        }
178	        return null;
179	    }
180	
181	    public Pet getPet(Integer petId) {
182	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
183	    }
184	
185	    @Override
186	    public String toString() {
187	        return new ToStringCreator(this)
188	
189	            .append("id", this.getId())
190	            .append("new", this.isNew())
191	            .append("lastName", this.getLastName())
192	            .append("firstName", this.getFirstName())
193	            .append("address", this.address)
194	            .append("city", this.city)
195	            .append("telephone", this.telephone)
196	            .append("email", this.email)
197	            .append("registrationDate", this.registrationDate)
198	            .append("customerCode", this.customerCode)
199	            .toString();
200	    }
201	}
