4	 * Converts a raw, user-supplied telephone number into E.164 form.
5	 *
6	 * <p>The rules are:
7	 * <ul>
8	 *     <li>spaces, dashes and brackets are stripped;</li>
9	 *     <li>a leading {@code '+'} and country code are kept when present;</li>
10	 *     <li>otherwise country code {@code '+61'} is assumed and a single leading
11	 *         {@code '0'} is dropped from the national digits;</li>
12	 *     <li>the result must carry 8 to 15 digits after the {@code '+'}.</li>
13	 * </ul>
14	 *
15	 * <p>So {@code "0412 345 678"} becomes {@code "+61412345678"} and
16	 * {@code "+64 21 123 456"} becomes {@code "+6421123456"}. The normalization is
17	 * idempotent: feeding it an already-E.164 value returns that same value.
18	 */
19	public final class E164Telephone {
20	
21	    private static final String DEFAULT_COUNTRY_CODE = "61";
22	
23	    private E164Telephone() {
24	    }
25	
26	    /**
27	     * Normalize a raw telephone number to E.164 form, or return {@code null} when the
28	     * input is {@code null} or cannot form a valid E.164 number.
29	     */
30	    public static String normalize(String raw) {
31	        if (raw == null) {
32	            return null;
33	        }
34	        // strip spaces, dashes and brackets
35	        String cleaned = raw.replaceAll("[\\s\\-()]", "");
36	        String digits;
37	        if (cleaned.startsWith("+")) {
38	            digits = cleaned.substring(1);
39	        } else {
40	            if (cleaned.startsWith("0")) {
41	                cleaned = cleaned.substring(1);
42	            }
43	            digits = DEFAULT_COUNTRY_CODE + cleaned;
44	        }
45	        if (!digits.matches("\\d{8,15}")) {
46	            return null;
47	        }
48	        return "+" + digits;
49	    }
50	
51	    /**
52	     * Whether the raw value can be converted to a valid E.164 number.
53	     */
54	    public static boolean isValid(String raw) {
55	        return normalize(raw) != null;
56	    }
57	}
